import * as THREE from 'three';
import { MeshStandardMaterial, MeshBasicMaterial } from 'three';
import { Pool } from '../../shared/utils/Pool.js';

class PlayerShip {
  constructor(scene, camera, renderer) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = renderer;

    // Player configuration
    this.speed = 5.0;
    this.width = 2.0;
    this.height = 1.0;
    this.depth = 0.3;
    this.position = { x: 0, y: -5, z: 0 };

    // Create player mesh
    this.mesh = this.createPlayerMesh();
    this.scene.add(this.mesh);

    // Create glow effect using MeshStandardMaterial with emissive
    const glowMaterial = new MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x0044ff,
      emissiveIntensity: 2.0,
      metalness: 0.8,
      roughness: 0.3,
      transparent: true,
      opacity: 0.95
    });

    this.mesh.material = glowMaterial;

    // Create trail effect mesh
    this.trailMesh = new THREE.Mesh(
      new THREE.BoxGeometry(this.width * 2, 0.1, this.depth * 2),
      new MeshBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.5 })
    );
    this.scene.add(this.trailMesh);

    // Create particle emitter for thrust effect
    this.thrustEmitter = new ParticleEmitter(scene, this.renderer, {
      position: { x: 0, y: -5, z: 0 },
      color: 0x00ffaa,
      speed: 2.0,
      count: 3
    });

    // Input state
    this.left = false;
    this.right = false;
    this.shooting = false;
    this.lastShootTime = 0;
    this.shootCooldown = 0.15;

    // Shooting cooldown timer
    this.shootTimer = 0;

    // Create pool for player bullets
    this.bulletPool = new Pool(20);
  }

  createPlayerMesh() {
    const geometry = new THREE.BoxGeometry(this.width, this.height, this.depth);
    return geometry;
  }

  update(deltaTime) {
    if (this.scene.camera && !this.scene.camera.visible) return;

    // Handle player movement
    if (this.left) {
      this.position.x -= this.speed * deltaTime;
    }
    if (this.right) {
      this.position.x += this.speed * deltaTime;
    }

    // Clamp position to screen bounds
    const maxBound = 10;
    this.position.x = Math.max(-maxBound, Math.min(maxBound, this.position.x));

    // Update mesh position
    this.mesh.position.set(this.position.x, this.position.y, this.position.z);

    // Update trail effect
    if (this.scene.camera && this.scene.camera.visible) {
      const trailPos = new THREE.Vector3(0, 0, 0);
      trailPos.copyFrom(this.mesh.position);
      this.trailMesh.position.copy(trailPos);
    }

    // Handle shooting
    this.shootTimer += deltaTime;
    if (this.shootTimer >= this.shootCooldown && this.shooting) {
      this.shoot();
      this.shootTimer = 0;
    }

    // Update thrust particle emitter
    this.thrustEmitter.update(deltaTime);
  }

  shoot() {
    const bullet = new Projectile(this.scene, this.renderer, {
      position: { x: this.position.x, y: -5.2, z: 0 },
      velocity: { x: 0, y: 8.0, z: 0 },
      color: 0x00ffaa,
      size: 0.3
    });

    bullet.active = true;
    this.scene.add(bullet.mesh);
    this.projectiles.push(bullet);
  }

  checkCollision(projectile) {
    const p = projectile;
    if (!p || !p.active) return false;

    // Check if projectile is within player bounds
    const dx = Math.abs(p.position.x - this.position.x);
    const dy = Math.abs(p.position.y - this.position.y);
    const dz = Math.abs(p.position.z - this.position.z);

    return (dx < 0.5 && dy < 1.5 && dz < 0.5);
  }

  respawn() {
    // Reset player position and state
    this.position.x = 0;
    this.position.y = -5;
    this.position.z = 0;
    this.mesh.position.set(0, -5, 0);
    this.shootTimer = 0;

    // Spawn respawn particles
    const particleSystem = this.scene.game?.particleSystem || null;
    if (particleSystem) {
      particleSystem.emit('explosion', 0, -5, 0, 1.5);
    }
  }

  dispose() {
    this.mesh.dispose();
    this.trailMesh.dispose();
    this.thrustEmitter?.dispose();
    for (const p of this.projectiles) {
      p.dispose();
    }
    this.bulletPool.clear();
  }
}

export default PlayerShip;
