    // Check for player projectiles hitting aliens
    for (let i = playerProjectiles.length - 1; i >= 0; i--) {
      const p = playerProjectiles[i];
      if (!p || !p.active) continue;

      let hitAlien = null;
      for (const alien of this.hitAliens) {
        if (!alien.active) continue;
        if (this.checkProjectileCollision(p, alien)) {
          hitAlien = alien;
          break;
        }
      }

      if (hitAlien) {
        this.handleAlienDeath(hitAlien);
        p.dispose();
        playerProjectiles.splice(i, 1);
        continue;
      }
    }

    // Check if aliens have reached the bottom
    const minY = this.startY - (this.rows - 1) * this.rowSpacing + this.alienHeight / 2;
    for (const alien of this.hitAliens) {
      if (!alien.active) continue;
      if (alien.y < minY - 5) {
        return true; // Game over
      }
    }

    return false;
  }

  moveAliens() {
    for (const alien of this.hitAliens) {
      if (!alien.active) continue;
      alien.x += this.moveSpeed * this.moveDirection;
    }
  }

  dropAliens() {
    for (const alien of this.hitAliens) {
      if (!alien.active) continue;
      alien.y -= this.dropDistance;
    }
  }

  checkProjectileCollision(projectile, target) {
    const p = projectile;
    if (!p || !p.active) return false;

    // AABB collision check
    const px = p.position.x;
    const py = p.position.y;
    const pz = p.position.z;
    const pr = 0.3; // Bullet radius for forgiving hitbox

    for (const alien of this.hitAliens) {
      if (!alien.active) continue;

      const ax = alien.x;
      const ay = alien.y;
      const az = alien.z;
      const aw = this.alienWidth / 2;
      const ah = this.alienHeight / 2;
      const ad = this.alienDepth / 2;

      // Check if bullet is within AABB bounds
      const closestX = Math.max(ax - aw, Math.min(px, ax + aw));
      const closestY = Math.max(ay - ah, Math.min(py, ay + ah));
      const closestZ = Math.max(az - ad, Math.min(pz, az + ad));

      const dx = px - closestX;
      const dy = py - closestY;
      const dz = pz - closestZ;

      if (dx * dx + dy * dy + dz * dz <= pr * pr) {
        return true;
      }
    }

    return false;
  }

  handleAlienDeath(alien) {
    // Spawn explosion particles at alien position
    const particleSystem = this.scene.game?.particleSystem || null;
    if (particleSystem) {
      particleSystem.emit('explosion', alien.x, alien.y, alien.z, 1.5);
    }

    // Screen shake based on impact velocity
    const cameraShake = this.scene.game?.cameraShake || null;
    if (cameraShake) {
      cameraShake.trigger(3.0);
    }

    // Spawn shockwave
    const shockwaveManager = this.scene.game?.shockwaveManager || null;
    if (shockwaveManager) {
      shockwaveManager.create(alien.x, alien.y, alien.z, 10, 0.6);
    }

    // Add score based on alien row
    const points = alien.points;
    this.scene.game.score += points;
    this.scene.game.updateScoreDisplay();

    // Spawn floating score text
    this.spawnFloatingText(alien.x, alien.y, `+${points}`, '#ffdd00');

    // Remove the hit alien from formation
    this.removeAlien(alien);
  }

  spawnFloatingText(x, y, text, color) {
    const scoreDisplay = this.scene.game?.scoreDisplay || null;
    if (scoreDisplay) {
      scoreDisplay.addFloatingText(x, y, text, color);
    }
  }

  removeAlien(alien) {
    alien.active = false;
    // Remove from active list
    const idx = this.activeAliens.indexOf(alien);
    if (idx !== -1) {
      this.activeAliens.splice(idx, 1);
    }
    // Return to pool for reuse
    this.alienPool.returnToPool(alien);

    // Remove from hit list
    const hitIdx = this.hitAliens.indexOf(alien);
    if (hitIdx !== -1) {
      this.hitAliens.splice(hitIdx, 1);
    }
  }

  getHitAlien(projectile) {
    for (const alien of this.hitAliens) {
      if (!alien.active) continue;
      const px = projectile.position.x;
      const py = projectile.position.y;
      const pz = projectile.position.z;
      const pr = 0.3;

      const ax = alien.x;
      const ay = alien.y;
      const az = alien.z;
      const aw = this.alienWidth / 2;
      const ah = this.alienHeight / 2;
      const ad = this.alienDepth / 2;

      const closestX = Math.max(ax - aw, Math.min(px, ax + aw));
      const closestY = Math.max(ay - ah, Math.min(py, ay + ah));
      const closestZ = Math.max(az - ad, Math.min(pz, az + ad));

      const dx = px - closestX;
      const dy = py - closestY;
      const dz = pz - closestZ;

      if (dx * dx + dy * dy + dz * dz <= pr * pr) {
        return alien;
      }
    }
    return null;
  }

  isDefeated() {
    return this.activeAliens.length === 0;
  }

  reset(waveNumber) {
    // Reset formation for new wave
    this.alienPool.clear();
    this.initFormation();
    this.enemyProjectiles = [];
  }

  dispose() {
    for (const alien of this.hitAliens) {
      if (alien.mesh) {
        alien.mesh.dispose();
      }
    }
    this.alienPool.clear();
    for (const p of this.enemyProjectiles) {
      p.dispose();
    }
  }
}

export default EnemyFormation;

/**
 * GameEngine - Core game loop and state management.
 */

class GameEngine {
  constructor() {
    this.gameState = 'menu'; // menu | playing | paused | gameOver
    this.running = false;
    this.paused = false;
    this.lastTime = 0;
    this.updateCallbacks = [];
    this.renderCallback = null;
    this.inputs = {};
  }

  /**
   * Start the game loop.
   */
  start() {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this._loop(this.lastTime);
  }

  /**
   * Main game loop.
   */
  _loop(timestamp) {
    if (!this.running) return;

    const deltaTime = Math.min((timestamp - this.lastTime) / 1000, 0.1); // Cap at 100ms
    this.lastTime = timestamp;

    // Update game state
    if (this.gameState === 'playing' && !this.paused) {
      for (const callback of this.updateCallbacks) {
        try {
          callback(deltaTime);
        } catch (e) {
          console.error('Update error:', e);
        }
      }
    }

    // Render if callback is registered
    if (this.renderCallback && this.running) {
      try {
        this.renderCallback();
      } catch (e) {
        console.error('Render error:', e);
      }
    }

    requestAnimationFrame((t) => this._loop(t));
  }

  /**
   * Register an update callback.
   */
  registerUpdate(callback) {
    if (!this.updateCallbacks.includes(callback)) {
      this.updateCallbacks.push(callback);
    }
  }

  /**
   * Register a render callback.
   */
  setRenderCallback(callback) {
    this.renderCallback = callback;
  }

  /**
   * Set the game state.
   */
  setState(newState) {
    if (newState !== this.gameState) {
      console.log(`Game state: ${this.gameState} -> ${newState}`);
      this.gameState = newState;
    }
  }

  /**
   * Pause the game loop.
   */
  pause() {
    this.paused = true;
  }

  /**
   * Resume the game loop.
   */
  resume() {
    this.paused = false;
  }

  /**
   * Stop the game loop.
   */
  stop() {
    this.running = false;
  }

  /**
   * Get current game state.
   */
  getState() {
    return this.gameState;
  }
}

export default GameEngine;

import * as THREE from 'three';
import { MeshStandardMaterial, MeshBasicMaterial } from 'three';
import { Pool } from '../../shared/utils/Pool.js';

class Projectile {
  constructor(scene, renderer, config = {}) {
    this.scene = scene;
    this.renderer = renderer;

    // Projectile configuration
    this.position = new THREE.Vector3(0, 0, 0);
    this.velocity = new THREE.Vector3(config.velocity || [0, 8, 0]);
    this.color = config.color || 0x00ffaa;
    this.size = config.size || 0.3;
    this.active = true;

    // Create projectile mesh (small glowing sphere)
    const geometry = new THREE.SphereGeometry(this.size * 2, 8, 6);
    const material = new MeshStandardMaterial({
      color: this.color,
      emissive: this.color,
      emissiveIntensity: 3.0,
      transparent: true,
      opacity: 0.95
    });

    this.mesh = new THREE.Mesh(geometry, material);
    this.scene.add(this.mesh);

    // Create glow ring around projectile
    const glowGeometry = new THREE.TorusGeometry(0.1, 0.02, 8, 32);
    const glowMaterial = new MeshBasicMaterial({ color: this.color, transparent: true, opacity: 0.7 });
    this.glowMesh = new THREE.Mesh(glowGeometry, glowMaterial);
    this.scene.add(this.glowMesh);

    // Create trail effect mesh
    const trailGeometry = new THREE.SphereGeometry(this.size * 3, 6, 4);
    const trailMaterial = new MeshBasicMaterial({ color: this.color, transparent: true, opacity: 0.3 });
    this.trailMesh = new THREE.Mesh(trailGeometry, trailMaterial);
    this.scene.add(this.trailMesh);

    // Lifetime tracking
    this.lifetime = config.lifetime || 4.0;
    this.elapsed = 0;
  }

  update(deltaTime) {
    if (!this.active) return;

    // Move projectile
    this.position.add(this.velocity * deltaTime);
    this.mesh.position.copy(this.position);

    // Update glow mesh position (slightly offset for visual effect)
    const glowOffset = new THREE.Vector3(0, 0.1, 0);
    glowOffset.scaleScalar(deltaTime);
    this.glowMesh.position.add(glowOffset);

    // Update trail mesh position
    this.trailMesh.position.copy(this.position);

    // Decrease lifetime
    this.elapsed += deltaTime;
    if (this.elapsed >= this.lifetime) {
      this.dispose();
    }
  }

  dispose() {
    if (!this.active) return;
    this.active = false;

    // Dispose of Three.js objects to prevent memory leaks
    this.mesh?.dispose();
    this.glowMesh?.dispose();
    this.trailMesh?.dispose();
  }

  get position() {
    return new THREE.Vector3(this.position.x, this.position.y, this.position.z);
  }

  set position(v) {
    if (v instanceof THREE.Vector3) {
      this.position.copy(v);
    } else {
      this.position.set(v[0], v[1], v[2]);
    }
  }
}

export default Projectile;

import * as THREE from 'three';
import { GameEngine } from '../shared/core/GameEngine.js';
import { InputHandler } from '../shared/core/InputHandler.js';
import { ParticleSystem } from '../shared/vfs/ParticleSystem.js';
import { CameraShake } from '../shared/vfs/CameraShake.js';
import { HitStop } from '../shared/vfs/HitStop.js';
import { MotionTrail } from '../shared/vfs/MotionTrail.js';
import { Shockwave } from '../shared/vfs/Shockwave.js';
import { PostProcessor } from './post-processing/PostProcessor.js';
import PlayerShip from './entities/Player.js';
import AlienFormation from './entities/EnemyFormation.js';
import Projectile from './entities/Projectile.js';
import ParticleEmitter from './entities/ParticleEmitter.js';
import ScoreDisplay from './ui/ScoreDisplay.js';
import LivesDisplay from './ui/LivesDisplay.js';
import WaveIndicator from './ui/WaveIndicator.js';

class SpaceInvaders {
  constructor() {
    this.engine = new GameEngine();
    this.inputHandler = new InputHandler();
    this.particleSystem = new ParticleSystem();
    this.cameraShake = new CameraShake();
    this.hitStop = new HitStop();
    this.trailManager = new MotionTrail(15);
    this.shockwaveManager = new Shockwave();

    // Game entities
    this.player = null;
    this.alienFormation = null;
    this.projectiles = [];
    this.enemyProjectiles = [];
    this.score = 0;
    this.lives = 3;
    this.wave = 1;
    this.gameState = 'menu';

    // Game configuration
    this.playerSpeed = 5.0;
    this.bulletSpeed = 8.0;
    this.enemyBulletSpeed = 4.0;
    this.alienMovementSpeed = 2.0;
    this.alienDropDistance = 10.0;

    // Initialize game systems
    this.init();
  }

  init() {
    // Set up Three.js scene
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x00001a, 0.005);

    // Create camera and renderer
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 20, 30);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // Set up post-processing
    this.postProcessor = new PostProcessor(scene, camera);
    this.postProcessor.init(scene, camera);

    // Initialize game entities
    this.player = new PlayerShip(scene, camera, renderer);
    this.alienFormation = new AlienFormation(scene, camera, renderer);
    this.projectiles = [];
    this.enemyProjectiles = [];

    // Register game update function
    this.engine.registerUpdate(this.update.bind(this));

    // Start the game loop
    this.engine.start();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Initialize UI
    const scoreDisplay = new ScoreDisplay(document.getElementById('score-display'));
    this.scoreDisplay = scoreDisplay;

    const livesDisplay = new LivesDisplay(document.getElementById('lives-display'));
    this.livesDisplay = livesDisplay;

    const waveIndicator = new WaveIndicator(document.getElementById('wave-indicator'));
    this.waveIndicator = waveIndicator;

    // Start game loop
    this.gameLoop();
  }

  update(deltaTime) {
    if (this.engine.gameState !== 'playing') return;

    // Update player
    this.player.update(deltaTime);

    // Update alien formation
    const gameOver = this.alienFormation.update(deltaTime, this.projectiles, this.enemyProjectiles);
    if (gameOver) {
      this.gameState = 'gameOver';
      this.engine.setState('gameOver');
      return;
    }

    // Update player projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      if (!p.active) continue;
      p.update(deltaTime);

      // Check projectile bounds
      if (p.y < -20 || p.y > 60) {
        p.dispose();
        this.projectiles.splice(i, 1);
        continue;
      }

      // Check player collision
      if (this.checkProjectileCollision(p, 'player')) {
        this.handlePlayerHit();
        p.dispose();
        this.projectiles.splice(i, 1);
        continue;
      }

      // Check enemy collision
      if (this.checkProjectileCollision(p, 'enemy')) {
        this.handleEnemyHit(p);
        p.dispose();
        this.projectiles.splice(i, 1);
        continue;
      }
    }

    // Update enemy projectiles
    for (let i = this.enemyProjectiles.length - 1; i >= 0; i--) {
      const p = this.enemyProjectiles[i];
      if (!p.active) continue;
      p.update(deltaTime);

      // Check projectile bounds
      if (p.y < -20 || p.y > 60) {
        p.dispose();
        this.enemyProjectiles.splice(i, 1);
        continue;
      }

      // Check player collision
      if (this.checkProjectileCollision(p, 'player')) {
        this.handlePlayerHit();
        p.dispose();
        this.enemyProjectiles.splice(i, 1);
        continue;
      }
    }

    // Update particle system
    this.particleSystem.update(deltaTime);

    // Update camera shake
    if (this.cameraShake.update(deltaTime)) {
      const offset = this.cameraShake.getOffset();
      this.scene.camera.position.x += offset[0];
      this.scene.camera.position.y += offset[1];
    } else {
      // Smoothly return to center
      this.scene.camera.position.lerp(0, 0, 0.1);
    }

    // Update hit-stop
    if (this.hitStop.active) {
      this.engine.paused = true;
    } else {
      this.engine.resume();
    }

    // Check game over conditions
    if (this.alienFormation.isDefeated()) {
      this.wave++;
      this.alienFormation.reset(this.wave);
      this.score += 100 * this.wave;
      this.updateScoreDisplay();
    } else if (this.lives <= 0) {
      this.gameState = 'gameOver';
      this.engine.setState('gameOver');
    }

    // Update score display
    this.updateScoreDisplay();
  }

  checkProjectileCollision(projectile, targetType) {
    const p = projectile;

    if (targetType === 'player') {
      return this.player.checkCollision(p);
    } else if (targetType === 'enemy') {
      return this.alienFormation.checkProjectileCollision(p);
    }

    return false;
  }

  handlePlayerHit() {
    // Trigger hit-stop effect
    this.hitStop.trigger(10.0);

    // Screen shake based on impact velocity
    this.cameraShake.trigger(5.0);

    // Spawn explosion particles at player position
    this.particleSystem.emit('explosion', this.player.position.x, this.player.position.y, this.player.position.z, 2);

    // Spawn shockwave
    this.shockwaveManager.create(this.player.position.x, this.player.position.y, this.player.position.z, 15, 0.8);

    // Reduce lives
    this.lives--;
    this.updateScoreDisplay();

    // Respawn player after delay
    setTimeout(() => {
      if (this.engine.gameState === 'playing') {
        this.player.respawn();
      }
    }, 2000);
  }

  handleEnemyHit(projectile) {
    // Get the alien that was hit
    const alien = this.alienFormation.getHitAlien(projectile);
    if (!alien) return;

    // Spawn explosion particles at alien position
    this.particleSystem.emit('explosion', alien.position.x, alien.position.y, alien.position.z, 1.5);

    // Screen shake based on impact velocity
    this.cameraShake.trigger(3.0);

    // Spawn shockwave
    this.shockwaveManager.create(alien.position.x, alien.position.y, alien.position.z, 10, 0.6);

    // Add score based on alien row
    const points = (5 - alien.row) * 10;
    this.score += points;
    this.updateScoreDisplay();

    // Spawn floating score text
    this.spawnFloatingText(alien.position.x, alien.position.y, `+${points}`, '#ffdd00');

    // Remove the hit alien from formation
    this.alienFormation.removeAlien(alien);
  }

  spawnFloatingText(x, y, text, color) {
    const scoreDisplay = this.scoreDisplay;
    if (scoreDisplay) {
      scoreDisplay.addFloatingText(x, y, text, color);
    }
  }

  updateScoreDisplay() {
    if (this.scoreDisplay) {
      this.scoreDisplay.update(this.score, this.lives, this.wave);
    }
    if (this.livesDisplay) {
      this.livesDisplay.updateLives(this.lives);
    }
    if (this.waveIndicator) {
      this.waveIndicator.updateWave(this.wave);
    }
  }

  dispose() {
    // Dispose of all Three.js objects to prevent memory leaks
    for (const p of this.projectiles) {
      p.dispose();
    }
    for (const p of this.enemyProjectiles) {
      p.dispose();
    }
    if (this.player) {
      this.player.dispose();
    }
    if (this.alienFormation) {
      this.alienFormation.dispose();
    }
    this.particleSystem.clear();
    this.shockwaveManager.clear();
    this.hitStop.reset();
    this.trailManager.clear();
    this.postProcessor?.dispose();
  }
}

export default SpaceInvaders;

