import { KeyboardController, MouseController } from 'three';

class InputHandler {
  constructor() {
    this.keyboard = new KeyboardController();
    this.mouse = new MouseController();
    this._boundKeyboard = false;
    this._boundMouse = false;
  }

  getInputs() {
    if (!this._boundKeyboard) {
      window.addEventListener('keydown', this.onKeyDown.bind(this));
      this._boundKeyboard = true;
    }
    if (!this._boundMouse) {
      window.addEventListener('mousemove', this.onMouseMove.bind(this));
      this._boundMouse = true;
    }
    return {
      left: () => this.keyboard.getKey('ArrowLeft'),
      right: () => this.keyboard.getKey('ArrowRight'),
      shoot: () => this.keyboard.getKey('Space'),
      mouseX: () => this.mouse.getX(),
      mouseY: () => this.mouse.getY()
    };
  }

  onKeyDown(e) {
    if (e.code === 'ArrowLeft' || e.code === 'KeyA') {
      this.keyboard.setDown('left');
    } else if (e.code === 'ArrowRight' || e.code === 'KeyD') {
      this.keyboard.setDown('right');
    } else if (e.code === 'Space') {
      this.keyboard.setDown('shoot');
    }
  }

  onMouseMove(e) {
    this.mouse.setPosition(e.clientX, e.clientY);
  }

  dispose() {
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('mousemove', this.onMouseMove);
    this._boundKeyboard = false;
    this._boundMouse = false;
  }
}

export default InputHandler;

/**
 * Pool - Object pooling utility for efficient resource management.
 * Reuses pre-allocated objects instead of creating/destroying them,
 * preventing memory leaks in long-running games.
 */

class Pool {
  constructor(maxSize = 100) {
    this.maxSize = maxSize;
    this.items = []; // Array of available pooled items
    this.inUse = new Map(); // Maps item to its current user
  }

  /**
   * Acquire an item from the pool. If none available, creates a new one.
   * @param {Function} factory - Function that creates a new item
   * @returns {Object|undefined} The acquired item or null if pool is exhausted
   */
  acquire(factory) {
    // Try to get an unused item from the pool
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      if (!this.inUse.has(item)) {
        this.items.splice(i, 1);
        return item;
      }
    }

    // Create a new item if pool is exhausted
    if (this.items.length < this.maxSize) {
      const item = factory();
      this.items.push(item);
      return item;
    }

    return null;
  }

  /**
   * Return an item to the pool for reuse.
   * @param {Object} item - The item to release back to the pool
   */
  release(item) {
    if (item && typeof item.dispose === 'function') {
      item.dispose();
    }
    this.inUse.delete(item);
    this.items.push(item);
  }

  /**
   * Get count of available items in the pool.
   */
  get size() {
    return this.items.length;
  }

  /**
   * Clear all items from the pool.
   */
  clear() {
    for (const item of this.items) {
      if (typeof item.dispose === 'function') {
        item.dispose();
      }
    }
    this.items = [];
    this.inUse.clear();
  }

  /**
   * Get count of currently in-use items.
   */
  get inUseCount() {
    return this.inUse.size;
  }

  /**
   * Get all available (unused) items.
   */
  getAvailableItems() {
    const result = [];
    for (const item of this.items) {
      if (!this.inUse.has(item)) {
        result.push(item);
      }
    }
    return result;
  }

  /**
   * Mark an item as in-use.
   */
  markInUse(item, user) {
    this.inUse.set(item, user);
  }

  /**
   * Unmark an item from use.
   */
  unmarkItem(item) {
    this.inUse.delete(item);
  }
}

export default Pool;

/**
 * ParticleSystem - Manages particle effects for explosions, thrust, etc.
 */

class ParticleSystem {
  constructor() {
    this.particles = []; // Array of active particles
    this._nextId = 0;
  }

  /**
   * Emit a burst of particles at the given position.
   * @param {string} type - Type of particle (explosion, thrust, etc.)
   * @param {number} x - X position
   * @param {number} y - Y position
   * @param {number} z - Z position
   * @param {number} count - Number of particles to emit
   */
  emit(type, x, y, z, count = 10) {
    const colors = {
      explosion: [0xff4444, 0xffaa00, 0x88ff00],
      thrust: [0x00ffaa, 0x00cc88, 0x00ffdd]
    };

    const colorPalette = colors[type] || colors.explosion;

    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 1.0 + Math.random() * 3.0;
      const particle = {
        x: x,
        y: y,
        z: z,
        vx: Math.cos(angle) * speed,
        vy: (Math.random() - 0.5) * speed,
        vz: (Math.random() - 0.5) * speed,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        size: 0.1 + Math.random() * 0.4,
        color: colorPalette[Math.floor(Math.random() * colorPalette.length)],
        id: this._nextId++
      };

      this.particles.push(particle);
    }
  }

  /**
   * Update all particles for one frame.
   */
  update(deltaTime) {
    const now = performance.now();

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      if (!p || !p.life) continue;

      // Update position
      p.x += p.vx * deltaTime;
      p.y += p.vy * deltaTime;
      p.z += p.vz * deltaTime;

      // Apply gravity to Y axis
      p.vy -= 9.81 * deltaTime;

      // Decay life
      p.life -= p.decay * deltaTime;

      // Remove dead particles
      if (p.life <= 0) {
        this.particles.splice(i, 1);
      }
    }
  }

  /**
   * Get all active particles.
   */
  getParticles() {
    return [...this.particles];
  }

  /**
   * Clear all particles.
   */
  clear() {
    this.particles = [];
  }

  /**
   * Get count of active particles.
   */
  get size() {
    return this.particles.length;
  }

  /**
   * Reset particle system with new ID counter.
   */
  reset() {
    this.clear();
    this._nextId = 0;
  }
}

export default ParticleSystem;

