/**
 * MathUtils - Vector and mathematical utilities for game physics
 */

// Simplex noise implementation (procedural displacement)
class SimplexNoise {
  constructor(seed = 0) {
    this.seed = seed;
    // Generate pseudo-random permutation table
    this.perm = new Uint8Array(256);
    for (let i = 0; i < 256; i++) {
      this.perm[i] = i;
    }
    // Fisher-Yates shuffle with seeded PRNG
    const rng = () => {
      let s = this.seed + Math.sin(Date.now() * 0.001) * 43758.5453;
      return (s - Math.floor(s)) * 65536 | 0;
    };
    for (let i = 255; i > 0; i--) {
      const j = rng() % (i + 1);
      [this.perm[i], this.perm[j]] = [this.perm[j], this.perm[i]];
    }
  }

  _hash(x, y) {
    return ((x * 374761393 | 0) ^ (y * 668265263 | 0)) & 0xFFFFFFFF;
  }

  _lerp(t, a, b) {
    return a + t * (b - a);
  }

  _f(t) {
    return t * t * t * (t * (7 * t - 15) + 6);
  }

  _grad(hash, x, y, z) {
    const u = hash & 0x3F;
    const v = (hash >> 6) & 0x3F;
    const w = (hash >> 12) & 0x3F;
    return ((u ^ (v | w)) << 1) + (v ^ (w | u)) + (w ^ (u | v));
  }

  _sample(x, y, z) {
    const ix = x | 0;
    const iy = y | 0;
    const iz = z | 0;
    const fx = x - ix;
    const fy = y - iy;
    const fz = z - iz;
    const u = this._lerp(fz, this._grad(this._hash(ix, iy, iz), fx, fy, 0),
                          this._grad(this._hash(ix, iy, iz + 1), fx, fy, 1));
    return this._lerp(fy, this._grad(this._hash(ix, iy, iz), u, 0, 0),
                      this._grad(this._hash(ix, iy, iz + 1), u, 0, 1));
  }

  // 2D noise for terrain/displacement
  noise2D(x, y) {
    return this._sample(x * 0.05, y * 0.05, 0);
  }

  // 3D noise for volumetric effects
  noise3D(x, y, z) {
    return this._sample(x * 0.1, y * 0.1, z * 0.1);
  }

  // Perlin-like gradient noise
  perlinNoise2D(x, y) {
    const ix = x | 0;
    const iy = y | 0;
    const fx = x - ix;
    const fy = y - iy;
    const u = this._lerp(fy, this._grad(this._hash(ix, iy), fx, 0, 0),
                          this._grad(this._hash(ix, iy + 1), fx, 0, 1));
    return this._lerp(fx, this._grad(this._hash(ix, iy), u, 0, 0),
                      this._grad(this._hash(ix, iy + 1), u, 0, 1));
  }

  // Smoothed noise with multiple octaves (fractal Brownian motion)
  fbm(x, y, octaves = 4, persistence = 0.5, lacunarity = 2.0) {
    let sum = 0;
    let amplitude = 1;
    let frequency = 1;

    for (let i = 0; i < octaves; i++) {
      sum += this.perlinNoise2D(x * frequency, y * frequency) * amplitude;
      amplitude *= persistence;
      frequency *= lacunarity;
    }
    return sum;
  }

  // Lerp helper
  lerp(a, b, t) {
    return a + (b - a) * t;
  }

  // Clamp value between min and max
  clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  // Random number in range [min, max]
  random(min = 0, max = 1) {
    return Math.random() * (max - min) + min;
  }

  // Distance between two points
  distance(x1, y1, x2, y2) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  // Normalize a vector
  normalize(x, y) {
    const len = Math.sqrt(x * x + y * y);
    if (len === 0) return [0, 0];
    return [x / len, y / len];
  }

  // Scale a vector
  scale(x, y, s) {
    return [x * s, y * s];
  }

  // Add two vectors
  add(x1, y1, x2, y2) {
    return [x1 + x2, y1 + y2];
  }

  // Subtract two vectors
  subtract(x1, y1, x2, y2) {
    return [x1 - x2, y1 - y2];
  }

  // Dot product of two vectors
  dot(x1, y1, x2, y2) {
    return x1 * x2 + y1 * y2;
  }

  // Cross product magnitude (2D)
  crossProduct2D(x1, y1, x2, y2) {
    return x1 * y2 - y1 * x2;
  }

  // Check if two AABBs collide
  aabbCollide(x1, y1, w1, h1, x2, y2, w2, h2) {
    return (x1 < x2 + w2 && x1 + w1 > x2 &&
            y1 < y2 + h2 && y1 + h1 > y2);
  }

  // Check if two circles collide
  circleCollide(x1, y1, r1, x2, y2, r2) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return (dx * dx + dy * dy < (r1 + r2) * (r1 + r2));
  }

  // Check if a point is inside a rectangle
  pointInRect(px, py, rx, ry, rw, rh) {
    return (px >= rx && px <= rx + rw && py >= ry && py <= ry + rh);
  }

  // Rotate a point around origin by angle in radians
  rotatePoint(x, y, angle) {
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    return [x * cos - y * sin, x * sin + y * cos];
  }

  // Convert polar to Cartesian coordinates
  polarToCartesian(r, theta) {
    return [r * Math.cos(theta), r * Math.sin(theta)];
  }

  // Convert Cartesian to polar coordinates
  cartesianToPolar(x, y) {
    const r = Math.sqrt(x * x + y * y);
    const theta = Math.atan2(y, x);
    return [r, theta];
  }

  // Smoothstep function for easing
  smoothstep(t) {
    return t * t * (3 - 2 * t * (t + 1));
  }

  // Ease out cubic
  easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  // Ease in-out quartic
  easeInOutQuartic(t) {
    const t4 = t * t * t * t;
    return t4 * (7 * t4 - 12 * t4 + 5);
  }
}

export default MathUtils;
