/**
 * Pool - Object pooling for game entities, projectiles, and particles
 * Prevents garbage collection overhead by reusing destroyed objects
 */

class Pool {
  constructor(initialSize = 10) {
    this.items = [];
    this.maxSize = initialSize;
    this._nextId = 0;
  }

  /**
   * Create a new item from the provided factory function.
   * If pool has free items, reuse one and call factory with (item, true).
   * Otherwise create a new instance and call factory with (item, false).
   */
  acquire(factory) {
    if (this.items.length > 0) {
      const item = this.items.pop();
      item._id = this._nextId++;
      factory(item, true);
      return item;
    }

    const item = factory();
    item._id = this._nextId++;
    this.items.push(item);
    factory(item, false);
    return item;
  }

  /**
   * Return an item to the pool. The item is reset to its default state.
   */
  release(item) {
    if (item && item._id !== undefined) {
      // Reset any game-specific state that might have been set
      if (typeof item.reset === 'function') {
        item.reset();
      }
      this.items.push(item);
    }
  }

  /**
   * Get the number of currently active items.
   */
  get size() {
    return this.items.length;
  }

  /**
   * Get all available (free) items.
   */
  get freeItems() {
    return [...this.items];
  }

  /**
   * Get all active (in-use) items.
   */
  get activeItems() {
    const total = this._nextId;
    const used = new Set();
    for (const item of this.items) {
      if (item._id !== undefined) {
        used.add(item._id);
      }
    }
    return Array.from({ length: total }, (_, i) => i).filter(id => !used.has(id));
  }

  /**
   * Clear all items from the pool.
   */
  clear() {
    for (const item of this.items) {
      if (typeof item.dispose === 'function') {
        item.dispose();
      }
    }
    this.items = [];
    this._nextId = 0;
  }

  /**
   * Get an item by its ID. Returns undefined if not found.
   */
  getById(id) {
    for (const item of this.items) {
      if (item._id === id) return item;
    }
    return undefined;
  }

  /**
   * Remove all items and dispose of them.
   */
  destroyAll() {
    this.clear();
  }
}

export default Pool;
