/**
 * Noise - Procedural noise generators for geometry displacement, terrain generation, etc.
 */

import SimplexNoise from './SimplexNoise.js';

class NoiseGenerator {
  constructor(seed = 0) {
    this.simplex = new SimplexNoise(seed);
  }

  // 2D Perlin-like noise (normalized -1 to 1)
  noise2D(x, y, scale = 1) {
    const val = this.simplex.perlinNoise2D(x * scale, y * scale);
    return (val + 1) / 2; // Normalize to 0-1 range
  }

  // 3D Perlin-like noise
  noise3D(x, y, z, scale = 1) {
    const val = this.simplex.noise3D(x * scale, y * scale, z * scale);
    return (val + 1) / 2;
  }

  // Fractal Brownian Motion - layered noise for natural-looking terrain
  fbm(x, y, octaves = 4, persistence = 0.5, lacunarity = 2.0, scale = 1) {
    let sum = 0;
    let amplitude = 1;
    let frequency = 1;

    for (let i = 0; i < octaves; i++) {
      const val = this.simplex.perlinNoise2D(x * frequency, y * frequency) * amplitude;
      sum += val;
      amplitude *= persistence;
      frequency *= lacunarity;
    }

    // Normalize to 0-1 range
    return Math.max(0, Math.min(1, (sum + 1) / 2));
  }

  // Gradient noise for smooth transitions
  gradientNoise(x, y, scale = 1) {
    const val = this.simplex.noise2D(x * scale, y * scale);
    return (val + 1) / 2;
  }

  // Random value based on position (for deterministic randomness)
  randomAt(x, y) {
    const val = this.simplex.noise2D(x, y);
    return (val + 1) / 2;
  }
}

export default NoiseGenerator;
