/**
 * ParticleSystem - Centralized particle manager with hard cap of 500 active particles.
 * Manages all VFX particles across the game (explosions, trails, ambient effects).
 */

import { Pool } from '../utils/Pool.js';

const MAX_PARTICLES = 500;

class ParticleSystem {
  constructor() {
    this.pool = new Pool(100); // Pre-allocate pool for particle objects
    this.activeParticles = [];
    this.maxCapacity = MAX_PARTICLES;
    this._nextId = 0;

    // Register default emitters (named by key)
    this.emitters = {};

    this.registerEmitter('explosion', {
      count: 30,
      speedRange: [2, 8],
      lifeRange: [0.5, 1.5],
      sizeRange: [2, 6],
      color: '#ff4444',
      type: 'burst'
    });

    this.registerEmitter('spark', {
      count: 15,
      speedRange: [3, 10],
      lifeRange: [0.3, 0.8],
      sizeRange: [1, 4],
      color: '#ffaa00',
      type: 'burst'
    });

    this.registerEmitter('ambient', {
      count: 5,
      speedRange: [0.2, 0.8],
      lifeRange: [2, 5],
      sizeRange: [1, 3],
      color: '#4488ff',
      type: 'drift'
    });

    this.registerEmitter('trail', {
      count: 3,
      speedRange: [0.1, 0.3],
      lifeRange: [0.2, 0.5],
      sizeRange: [2, 4],
      color: '#ff66aa',
      type: 'trail'
    });

    this.registerEmitter('shockwave', {
      count: 1,
      speedRange: [5, 15],
      lifeRange: [0.8, 1.2],
      sizeRange: [8, 20],
      color: '#44ffaa',
      type: 'ring'
    });

    this.registerEmitter('death', {
      count: 40,
      speedRange: [3, 12],
      lifeRange: [0.5, 2.0],
      sizeRange: [2, 8],
      color: '#ff44aa',
      type: 'burst'
    });

    this.registerEmitter('score', {
      count: 20,
      speedRange: [1, 4],
      lifeRange: [1.5, 3.0],
      sizeRange: [3, 7],
      color: '#ffdd00',
      type: 'burst'
    });

    this._spawnTimer = 0;
    this._ambientSpawnInterval = 2.0; // Spawn ambient particles every 2 seconds
  }

  registerEmitter(name, config) {
    this.emitters[name] = config;
  }

  /**
   * Emit particles using a named emitter configuration.
   */
  emit(name, x, y, z, countMultiplier = 1) {
    const emitter = this.emitters[name];
    if (!emitter) return;

    const count = Math.floor(emitter.count * countMultiplier);

    for (let i = 0; i < count; i++) {
      this._spawnParticle(x, y, z, emitter, i);
    }
  }

  /**
   * Spawn a single particle from the pool.
   */
  _spawnParticle(x, y, z, config, index) {
    // Check capacity cap - evict oldest if at max
    while (this.activeParticles.length >= this.maxCapacity) {
      const oldest = this.activeParticles.shift();
      if (oldest && typeof oldest.dispose === 'function') {
        oldest.dispose();
      }
    }

    const item = this.pool.acquire((item) => {
      item.x = x;
      item.y = y;
      item.z = z;
      item.active = true;
      item._id = this._nextId++;
      item._spawnTime = performance.now();

      // Randomize position slightly around spawn point
      const spread = config.sizeRange[0] * 0.5;
      item.x += (Math.random() - 0.5) * spread;
      item.y += (Math.random() - 0.5) * spread;
      item.z += (Math.random() - 0.5) * spread;

      // Randomize velocity based on emitter type
      const speed = config.speedRange[0] + Math.random() * (config.speedRange[1] - config.speedRange[0]);
      if (config.type === 'burst') {
        item.vx = (Math.random() - 0.5) * speed;
        item.vy = (Math.random() - 0.5) * speed;
        item.vz = (Math.random() - 0.5) * speed;
      } else if (config.type === 'trail') {
        // Trail particles move in opposite direction of parent
        item.vx = (Math.random() - 0.5) * speed * 0.3;
        item.vy = (Math.random() - 0.5) * speed * 0.3;
        item.vz = (Math.random() - 0.5) * speed * 0.3;
      } else if (config.type === 'ring') {
        // Ring particles expand outward in a circle
        const angle = Math.random() * Math.PI * 2;
        item.vx = Math.cos(angle) * speed;
        item.vy = 0;
        item.vz = Math.sin(angle) * speed;
      } else {
        item.vx = (Math.random() - 0.5) * speed;
        item.vy = (Math.random() - 0.5) * speed;
        item.vz = (Math.random() - 0.5) * speed;
      }

      // Randomize life duration
      const life = config.lifeRange[0] + Math.random() * (config.lifeRange[1] - config.lifeRange[0]);
      item.life = life;
      item.maxLife = life;

      // Randomize size over lifetime
      item.size = config.sizeRange[0];
      item.maxSize = config.sizeRange[1];
      item.alpha = 1.0;

      // Color with slight variation
      const baseColor = config.color;
      const r = parseInt(baseColor.slice(1, 3), 16);
      const g = parseInt(baseColor.slice(3, 5), 16);
      const b = parseInt(baseColor.slice(5, 7), 16);
      item.r = r + (Math.random() - 0.5) * 40;
      item.g = g + (Math.random() - 0.5) * 40;
      item.b = b + (Math.random() - 0.5) * 40;

      // Store reference to Three.js particle mesh for disposal
      item.mesh = null;
    });

    this.activeParticles.push(item);
  }

  /**
   * Update all active particles by one frame.
   */
  update(deltaTime) {
    const now = performance.now();

    // Spawn ambient particles periodically
    this._spawnTimer += deltaTime;
    if (this._spawnTimer >= this._ambientSpawnInterval) {
      this._spawnTimer = 0;
      this.emit('ambient', Math.random() * 10 - 5, 2 + Math.random() * 3, Math.random() * 10 - 5);
    }

    // Update and remove dead particles
    for (let i = this.activeParticles.length - 1; i >= 0; i--) {
      const p = this.activeParticles[i];
      if (!p || !p.active) continue;

      // Update position
      p.x += p.vx * deltaTime;
      p.y += p.vy * deltaTime;
      p.z += p.vz * deltaTime;

      // Apply gravity for burst particles
      if (['burst', 'death'].includes(p.type)) {
        p.vy -= 50 * deltaTime; // Gravity effect
      }

      // Decay size and alpha over lifetime
      const age = now - p._spawnTime;
      const progress = Math.min(age / p.maxLife, 1);
      p.alpha = 1.0 - progress;
      p.size = p.size + (p.maxSize - p.size) * progress;

      // Remove dead particles
      if (progress >= 1 || p.alpha <= 0) {
        this.release(p);
        this.activeParticles.splice(i, 1);
      }
    }
  }

  /**
   * Release a particle back to the pool.
   */
  release(item) {
    if (item && typeof item.dispose === 'function') {
      item.dispose();
    }
  }

  /**
   * Get count of active particles.
   */
  get size() {
    return this.activeParticles.length;
  }

  /**
   * Clear all particles immediately.
   */
  clear() {
    for (const p of this.activeParticles) {
      this.release(p);
    }
    this.activeParticles = [];
    this._spawnTimer = 0;
  }

  /**
   * Get particle data for rendering.
   */
  getParticleData() {
    return this.activeParticles.map(p => ({
      x: p.x, y: p.y, z: p.z,
      size: p.size, alpha: p.alpha,
      r: Math.max(0, Math.min(255, p.r)),
      g: Math.max(0, Math.min(255, p.g)),
      b: Math.max(0, Math.min(255, p.b))
    }));
  }

  /**
   * Get particle count for UI display.
   */
  getCount() {
    return this.activeParticles.length;
  }
}

