 * Creates a brief "freeze" effect that stretches time perception on impacts.
 */

class HitStop {
  constructor() {
    this.active = false;
    this.scaleFactor = 1.0; // Time dilation multiplier (e.g., 0.25 = 4x slow)
    this.maxScale = 0.3; // Maximum time dilation
    this.minDuration = 0.05; // Minimum duration in seconds
    this.maxDuration = 0.3; // Maximum duration in seconds

    // Impact tracking for cumulative hit-stop
    this.impactHistory = [];
    this._lastImpactTime = 0;
  }

  /**
   * Trigger hit-stop based on impact severity.
   * Higher severity = more dramatic freeze effect.
   */
  trigger(severity) {
    const now = performance.now();
    const timeSinceLast = (now - this._lastImpactTime) / 1000;

    // Decay previous impacts over time
    if (timeSinceLast < 0.3) {
      // Cumulative hit-stop: add to current duration
      this.scaleFactor += severity * 0.2;
    } else {
      // New independent impact
      this.scaleFactor = Math.min(this.maxScale, severity * 0.5);
    }

    this._lastImpactTime = now;
    this.active = true;
  }

  /**
   * Update hit-stop for one frame. Returns false when inactive.
   */
  update(deltaTime) {
    if (!this.active || this.scaleFactor <= 1.0) {
      this.active = false;
      return false;
    }

    // Decay the time dilation effect
    const decayRate = 20.0; // How fast hit-stop fades per second
    this.scaleFactor -= deltaTime * decayRate;

    if (this.scaleFactor <= 1.0) {
      this.active = false;
    }
  }

  /**
   * Get the current time dilation scale factor.
   */
  getScale() {
    return this.scaleFactor;
  }

  /**
   * Reset hit-stop to normal time.
   */
  reset() {
    this.active = false;
    this.scaleFactor = 1.0;
    this.impactHistory = [];
  }
}

