/**
 * PostProcessor - Three.js post-processing chain configuration.
 * Sets up EffectComposer with UnrealBloomPass for neon glow effects.
 */

import { EffectComposer, RenderPass } from 'three';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

class PostProcessor {
  constructor(scene) {
    this.scene = scene;
    this.composer = new EffectComposer();
    this.bloomPass = null;
    this.toneCurvePass = null;
    this.setupPostProcessing();
  }

  setupPostProcessing() {
    // Create render pass for the main camera
    const renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(renderPass);

    // Configure UnrealBloomPass for neon glow effect
    this.bloomPass = new UnrealBloomPass({
      radius: 0.8,
      threshold: 0.5,
      bloomStrength: 1.2,
      minThreshold: 0.0,
      maxThreshold: 1.0
    });

    // Add tone curve pass for contrast enhancement
    this.toneCurvePass = new ToneCurvePass({
      tones: [
        { r: [0, 0], g: [0, 0], b: [0, 0] },
        { r: [0.15, 0.3], g: [0.2, 0.4], b: [0.25, 0.6] }
      ]
    });

    this.composer.addPass(this.bloomPass);
    this.composer.addPass(this.toneCurvePass);

    // Set up the camera for post-processing
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 20, 30);
    camera.lookAt(0, 0, 0);

    // Add post-processing camera to scene
    this.scene.add(new THREE.Group().setPosition(camera.position));
    this.scene.add(new THREE.Group().setRotation(camera.rotation).add(camera));

    // Set the composer's camera
    this.composer.setCamera(camera);
  }

  render(renderer) {
    if (this.composer) {
      this.composer.render(renderer, this.camera);
    }
  }

  getBloomPass() {
    return this.bloomPass;
  }

  setBloomStrength(strength) {
    if (this.bloomPass) {
      this.bloomPass.bloomStrength = strength;
    }
  }

  setBloomRadius(radius) {
    if (this.bloomPass) {
      this.bloomPass.radius = radius;
    }
  }

  dispose() {
    if (this.composer) {
      this.composer.dispose();
    }
  }
}

export default PostProcessor;
