import * as THREE from 'three';
import { MeshStandardMaterial, MeshBasicMaterial } from 'three';
import { Pool } from '../../shared/utils/Pool.js';

class AlienFormation {
  constructor(scene, camera, renderer) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = renderer;

    // Alien configuration
    this.rows = 5;
    this.columns = 11;
    this.alienWidth = 2.0;
    this.alienHeight = 1.5;
    this.alienDepth = 0.8;
    this.rowSpacing = 3.0;
    this.columnSpacing = 3.0;
    this.startX = -15;
    this.startY = 20;
    this.startZ = 0;

    // Movement configuration
    this.moveSpeed = 2.0;
    this.dropDistance = 10.0;
    this.moveDirection = 1; // 1 for right, -1 for left
    this.moveTimer = 0;
    this.moveInterval = 1.0;

    // Alien types with different point values and colors
    this.alienTypes = [
      { points: 30, color: 0x44ffaa },   // Top row - squid
      { points: 20, color: 0x88ffaa },   // Second row - crab
      { points: 10, color: 0xffaa44 },   // Third row - octopus
      { points: 5, color: 0xff6644 },    // Fourth row - squid
      { points: 3, color: 0x88ff44 }     // Bottom row - crab
    ];

    // Create alien meshes using object pooling
    this.alienPool = new Pool(55);
    this.activeAliens = [];
    this.hitAliens = [];

    // Create projectile pool for enemy bullets
    this.enemyBulletPool = new Pool(20);
    this.enemyProjectiles = [];

    // Initialize alien formation
    this.initFormation();
  }

  initFormation() {
    // Clear existing aliens
    this.activeAliens = [];
    this.hitAliens = [];

    // Create aliens for each row
    for (let row = 0; row < this.rows; row++) {
      const alienType = this.alienTypes[row];
      for (let col = 0; col < this.columns; col++) {
        const alien = this.createAlien(row, col, alienType);
        if (alien) {
          this.activeAliens.push(alien);
        }
      }
    }

    // Set initial movement direction based on wave number
    this.moveDirection = 1;
    this.moveTimer = 0;
  }

  createAlien(row, col, alienType) {
    const x = this.startX + col * this.columnSpacing;
    const y = this.startY - row * this.rowSpacing;
    const z = this.startZ;

    // Create alien mesh using object pooling
    const item = this.alienPool.acquire((item) => {
      const geometry = new THREE.BoxGeometry(
        this.alienWidth,
        this.alienHeight,
        this.alienDepth
      );

      const material = new MeshStandardMaterial({
        color: alienType.color,
        emissive: alienType.color * 0.5,
        emissiveIntensity: 1.0,
        metalness: 0.7,
        roughness: 0.3
      });

      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(x, y, z);
      this.scene.add(mesh);

      // Store alien data
      item.x = x;
      item.y = y;
      item.z = z;
      item.row = row;
      item.col = col;
      item.points = alienType.points;
      item.color = alienType.color;
      item.active = true;
      item.mesh = mesh;

      return item;
    });

    if (item) {
      this.hitAliens.push(item);
    }

    return item;
